function updateRatSim() {
    const x = parseInt(document.getElementById('input-rat-x').value, 10);
    document.getElementById('badge-rat-x').innerText = 'x = ' + x;

    const denom = x - 9;
    const num = x - 2;

    const dEl = document.getElementById('denom-val');
    const fEl = document.getElementById('frac-val');
    const box = document.getElementById('rat-status-box');
    const title = document.getElementById('rat-title');
    const desc = document.getElementById('rat-desc');

    if (denom === 0) {
        dEl.innerText = '0 (UNDEFINED!)';
        fEl.innerText = 'Undefined';
        box.style.background = 'rgba(225, 29, 72, 0.15)';
        box.style.borderColor = '#f43f5e';
        title.style.color = '#f43f5e';
        title.innerHTML = '<i class="fas fa-ban"></i> NON-PERMISSIBLE VALUE!';
        desc.innerText = 'At x = 9, the denominator is 9 - 9 = 0. Division by zero is undefined!';
    } else {
        const val = num / denom;
        dEl.innerText = denom;
        fEl.innerText = `${num} / ${denom} = ${val.toFixed(2)}`;

        if (x === 16) {
            box.style.background = 'rgba(16, 185, 129, 0.15)';
            box.style.borderColor = '#10b981';
            title.style.color = '#10b981';
            title.innerHTML = '<i class="fas fa-check-circle"></i> EXACT SOLUTION FOUND!';
            desc.innerText = `At x = 16: (16 - 2) / (16 - 9) = 14 / 7 = 2. Exactly matches RHS!`;
        } else {
            box.style.background = 'rgba(0, 0, 0, 0.2)';
            box.style.borderColor = 'var(--color-border)';
            title.style.color = 'var(--color-text-default)';
            title.innerHTML = '<i class="fas fa-calculator"></i> Valid Domain Point';
            desc.innerText = `Value is defined (${val.toFixed(2)}), but does not equal 2.`;
        }
    }
}

document.addEventListener('DOMContentLoaded', () => {
    updateRatSim();
});
